package cn.binbin.crm;
import jakarta.validation.constraints.*;import java.util.*;import java.time.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import org.springframework.stereotype.Service;import static cn.binbin.crm.TradeService.*;import static cn.binbin.crm.P3Base.map;
@Service
public class ExtendedWorkspaceService {
 public record Values(@NotNull @Size(max=100) Map<UUID,Object> values,@NotNull @Size(max=100) Map<UUID,Long> versions,@Min(0) long expectedRecordVersion){}
 public record Policy(@NotNull @Pattern(regexp="TENANT_ADMIN|SALES_MANAGER|SALES|VIEWER") String roleCode,boolean canRead,boolean canWrite,@Min(0) long expectedVersion){}
 private final P7Records r;private final P3Base b;private final P7Permissions p;private final ObjectStore storage;
 public ExtendedWorkspaceService(P7Records r,P7Permissions p,ObjectStore storage){this.r=r;this.b=r.b;this.p=p;this.storage=storage;}
 private Map<String,Object> fieldView(Map<String,Object> raw){var f=new LinkedHashMap<>(raw);f.put("options",parse(f.get("options")));return f;}
 private Object parse(Object raw){if(raw==null)return null;try{return b.data.json.readValue(String.valueOf(raw),Object.class);}catch(Exception e){throw new IllegalStateException(e);}}
 private boolean locked(String type,Map<String,Object> record){String state=String.valueOf(record.get("status"));return Set.of("RECEIPT","INVOICE","CONTRACT").contains(type)&&!state.equals("DRAFT")||type.equals("COMMISSION")&&state.equals("LOCKED")||type.equals("WEEKLY")&&!state.equals("DRAFT")||state.equals("VOID");}
 private Map<String,Object> writable(AuthService.Actor a,String type,UUID id){var record=r.get(a,type,id,true);if(locked(type,record))throw ApiError.forbidden("该记录已确认或锁定，扩展资料与附件保留只读历史");return record;}
 public Object extensions(AuthService.Session s,String type,UUID id){return r.scope(s,type,false,a->{var source=r.get(a,type,id,false);source.put("canWrite",Boolean.TRUE.equals(source.get("canWrite"))&&!locked(type,source));var args=map("tenant",a.tenant().id(),"type",type,"id",id,"roles",a.tenant().roles().toArray(String[]::new));var fields=b.rows("SELECT *,write_roles && cast(:roles AS text[]) AS can_write FROM crm_custom_field WHERE tenant_id=:tenant AND entity_type=:type AND status='ACTIVE' AND read_roles && cast(:roles AS text[]) ORDER BY section_name,position,id",args).stream().map(this::fieldView).toList();var values=b.rows("SELECT v.field_id,v.value,v.version FROM crm_custom_value v JOIN crm_custom_field f ON f.tenant_id=v.tenant_id AND f.id=v.field_id AND f.entity_type=v.entity_type WHERE v.tenant_id=:tenant AND v.entity_type=:type AND v.record_id=:id AND f.status='ACTIVE' AND f.read_roles && cast(:roles AS text[])",args);values.forEach(v->v.put("value",parse(v.get("value"))));return map("record",r.summary(source),"fields",fields,"values",values);});}
 private void validate(Map<String,Object> f,Object value){String label=String.valueOf(f.get("label"));if(value==null||value instanceof String str&&str.isBlank()||value instanceof Collection<?> list&&list.isEmpty()){if(Boolean.TRUE.equals(f.get("required")))throw ApiError.bad("请填写"+label);return;}String kind=String.valueOf(f.get("dataType"));boolean valid=switch(kind){case "NUMBER"->value instanceof Number||value instanceof String str&&str.matches("-?[0-9]{1,18}(\\.[0-9]{1,6})?");case "BOOLEAN"->value instanceof Boolean;case "MULTI_SELECT"->value instanceof List<?> list&&list.size()<=100&&list.stream().allMatch(v->v instanceof String);default->value instanceof String;};if(!valid||String.valueOf(value).length()>4000)throw ApiError.bad(label+"的值或长度无效");if(kind.equals("DATE"))try{date(LocalDate.parse(String.valueOf(value)));}catch(Exception e){throw ApiError.bad(label+"需填写有效日期");}if(Set.of("SELECT","MULTI_SELECT").contains(kind)){List<?> choices=(List<?>)parse(f.get("options"));if(kind.equals("SELECT")&&!choices.contains(value)||kind.equals("MULTI_SELECT")&&!choices.containsAll((List<?>)value))throw ApiError.bad(label+"包含未配置的选项");}}
 public Object save(AuthService.Session s,String type,UUID id,Values i,UUID trace){return r.scope(s,type,true,a->{p.feature(a,"workspace");var source=writable(a,type,id);if(number(source,"version")!=i.expectedRecordVersion())throw ApiError.conflict("业务记录已变化，请刷新");var args=map("tenant",a.tenant().id(),"type",type,"id",id,"roles",a.tenant().roles().toArray(String[]::new));var fields=b.rows("SELECT * FROM crm_custom_field WHERE tenant_id=:tenant AND entity_type=:type AND status='ACTIVE' AND write_roles && cast(:roles AS text[])",args);Map<UUID,Map<String,Object>> byId=new HashMap<>();for(var f:fields)byId.put((UUID)f.get("id"),f);for(UUID field:i.values().keySet())if(!byId.containsKey(field))throw ApiError.forbidden("字段不存在或没有写入权限");for(var f:fields){UUID field=(UUID)f.get("id");Object value=i.values().get(field);if(!i.values().containsKey(field)){var old=b.rows("SELECT value FROM crm_custom_value WHERE tenant_id=:tenant AND field_id=:field AND record_id=:record",map("tenant",a.tenant().id(),"field",field,"record",id));value=old.isEmpty()?null:parse(old.getFirst().get("value"));}validate(f,value);}
  for(var e:i.values().entrySet()){long expected=i.versions().getOrDefault(e.getKey(),-1L);var v=map("tenant",a.tenant().id(),"field",e.getKey(),"record",id,"expected",expected,"value",b.json(e.getValue()),"member",a.tenant().memberId(),"type",type,"id",UUID.randomUUID());var old=b.rows("SELECT version FROM crm_custom_value WHERE tenant_id=:tenant AND field_id=:field AND record_id=:record FOR UPDATE",v);long actual=old.isEmpty()?-1:number(old.getFirst(),"version");if(actual!=expected)throw ApiError.conflict("扩展字段已被其他人修改，请刷新");boolean blank=e.getValue()==null||e.getValue() instanceof String text&&text.isBlank();if(blank)b.db.update("DELETE FROM crm_custom_value WHERE tenant_id=:tenant AND field_id=:field AND record_id=:record",v);else if(old.isEmpty())b.db.update("INSERT INTO crm_custom_value(id,tenant_id,field_id,entity_type,record_id,value,updated_by_member_id) VALUES(:id,:tenant,:field,:type,:record,cast(:value AS jsonb),:member)",v);else b.db.update("UPDATE crm_custom_value SET value=cast(:value AS jsonb),updated_by_member_id=:member,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND field_id=:field AND record_id=:record AND version=:expected",v);}
  b.audit(a,"WORKSPACE_FIELDS_UPDATED",type,id,i.expectedRecordVersion(),trace);return extensions(s,type,id);});}
 public Object policies(AuthService.Session s){return b.tx.execute(st->{var a=b.auth.actor(s);p.admin(a);return map("items",b.rows("SELECT * FROM crm_object_policy WHERE tenant_id=:tenant ORDER BY entity_type,role_code",map("tenant",a.tenant().id())),"objects",P7Records.NAMES);});}
 public Object policy(AuthService.Session s,String type,Policy i,UUID trace){r.type(type);if(!Set.of("ORDER","INVOICE","EXPENSE","TARGET","COMMISSION","WEEKLY").contains(type))throw ApiError.bad("该对象请使用原角色权限管理");return b.tx.execute(st->{b.db.queryForObject("SELECT id FROM sys_tenant WHERE id=:tenant FOR UPDATE",map("tenant",s.tenantId()),UUID.class);var a=b.auth.actor(s);p.admin(a);p.feature(a,"workspace");if(i.canWrite()&&!i.canRead()||i.roleCode().equals("VIEWER")&&i.canWrite())throw ApiError.bad("写入需同时允许读取，只读成员不能获得写入权限");var args=map("tenant",a.tenant().id(),"type",type,"role",i.roleCode(),"read",i.canRead(),"write",i.canWrite(),"version",i.expectedVersion());b.db.update("INSERT INTO crm_object_policy(tenant_id,entity_type,role_code,can_read,can_write) SELECT tenant_id,:type,role_code,role_code<>'TENANT_ADMIN',role_code IN('SALES_MANAGER','SALES') FROM sys_role_policy WHERE tenant_id=:tenant ON CONFLICT DO NOTHING",args);if(b.db.update("UPDATE crm_object_policy SET can_read=:read,can_write=:write,version=version+1 WHERE tenant_id=:tenant AND entity_type=:type AND role_code=:role AND version=:version",args)!=1)throw ApiError.conflict("对象权限已变化，请刷新");b.audit(a,"OBJECT_POLICY_UPDATED",type,null,i.expectedVersion()+1,trace);return policies(s);});}
 public Object notices(AuthService.Session s){return b.tx.execute(st->{var a=b.auth.actor(s);if(a.supportGrantId()!=null)throw ApiError.forbidden("支持授权不含业务通知");var items=new ArrayList<Map<String,Object>>();for(var row:b.rows("SELECT * FROM crm_workspace_notice WHERE tenant_id=:tenant AND member_id=:member ORDER BY created_at DESC,id LIMIT 200",map("tenant",a.tenant().id(),"member",a.tenant().memberId())))try{var record=r.get(a,(String)row.get("entityType"),(UUID)row.get("recordId"),false);row.put("recordTitle",record.get("recordTitle"));items.add(row);}catch(ApiError hidden){}return map("items",items,"unread",items.stream().filter(n->n.get("readAt")==null).count());});}
 public Object noticeRead(AuthService.Session s,UUID id){return b.tx.execute(st->{var a=b.auth.actor(s);var row=b.one("SELECT * FROM crm_workspace_notice WHERE tenant_id=:tenant AND member_id=:member AND id=:id",map("tenant",a.tenant().id(),"member",a.tenant().memberId(),"id",id));r.get(a,(String)row.get("entityType"),(UUID)row.get("recordId"),false);b.db.update("UPDATE crm_workspace_notice SET read_at=coalesce(read_at,now()) WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id));return map("read",true);});}
 private void attachment(AuthService.Actor a,boolean write){if(!a.deliveryAccess().attachmentRead()||write&&!a.deliveryAccess().attachmentWrite())throw ApiError.forbidden("没有业务附件权限");}
 public Object files(AuthService.Session s,String type,UUID id){return r.scope(s,type,false,a->{attachment(a,false);r.get(a,type,id,false);return map("items",b.rows("SELECT id,file_name,content_type,size_bytes,sha256,version,created_at FROM crm_workspace_attachment WHERE tenant_id=:tenant AND entity_type=:type AND record_id=:record AND status='READY' ORDER BY created_at DESC,id",map("tenant",a.tenant().id(),"type",type,"record",id)),"storageConfigured",storage.configured());});}
 private String sha(byte[] bytes){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}catch(Exception e){throw new IllegalStateException(e);}}
 public Object upload(AuthService.Session s,String type,UUID record,String name,byte[] bytes,String key,UUID trace){String file=AttachmentService.filename(name),mime=AttachmentService.fileType(file,bytes),hash=sha(bytes);UUID attachment=UUID.randomUUID();String object=storage.key(s.tenantId(),attachment);boolean[] stored={false};try{return r.scope(s,type,true,a->{p.feature(a,"workspace");attachment(a,true);writable(a,type,record);UUID result=b.once(a,"workspace.attachment",key,map("type",type,"record",record,"file",file,"hash",hash),()->{var quota=b.one("SELECT t.attachment_bytes,p.storage_limit_bytes FROM sys_tenant t JOIN sys_plan p ON p.id=t.plan_id WHERE t.id=:tenant",map("tenant",a.tenant().id()));if(number(quota,"attachmentBytes")+bytes.length>number(quota,"storageLimitBytes"))throw ApiError.conflict("附件容量已达到套餐上限");stored[0]=true;storage.put(object,bytes,mime);b.db.update("INSERT INTO crm_workspace_attachment(id,tenant_id,entity_type,record_id,file_name,content_type,size_bytes,sha256,object_key,uploaded_by_member_id) VALUES(:id,:tenant,:type,:record,:file,:mime,:bytes,:hash,:object,:member)",map("id",attachment,"tenant",a.tenant().id(),"type",type,"record",record,"file",file,"mime",mime,"bytes",bytes.length,"hash",hash,"object",object,"member",a.tenant().memberId()));b.audit(a,"WORKSPACE_ATTACHMENT_UPLOADED",type,record,0,trace);return attachment;});return map("id",result,"fileName",file);});}catch(RuntimeException failure){if(stored[0])try{storage.delete(object);}catch(Exception cleanup){b.tx.executeWithoutResult(st->{b.context(s.tenantId());b.db.update("INSERT INTO sys_object_cleanup(id,tenant_id,object_key) VALUES(:id,:tenant,:key) ON CONFLICT DO NOTHING",map("id",UUID.randomUUID(),"tenant",s.tenantId(),"key",object));});}throw failure;}}
 public AttachmentService.Download download(AuthService.Session s,UUID id,UUID trace){return b.tx.execute(st->{var a=b.auth.actor(s);attachment(a,false);var row=b.one("SELECT * FROM crm_workspace_attachment WHERE tenant_id=:tenant AND id=:id AND status='READY'",map("tenant",a.tenant().id(),"id",id));r.get(a,(String)row.get("entityType"),(UUID)row.get("recordId"),false);byte[] bytes=storage.get((String)row.get("objectKey"));if(bytes.length!=number(row,"sizeBytes")||!sha(bytes).equals(row.get("sha256")))throw ApiError.conflict("附件完整性校验失败");b.audit(a,"WORKSPACE_ATTACHMENT_DOWNLOADED",(String)row.get("entityType"),(UUID)row.get("recordId"),number(row,"version"),trace);return new AttachmentService.Download((String)row.get("fileName"),(String)row.get("contentType"),bytes);});}
 public Object remove(AuthService.Session s,UUID id,long expected,UUID trace){return b.tx.execute(st->{b.db.queryForObject("SELECT id FROM sys_tenant WHERE id=:tenant FOR UPDATE",map("tenant",s.tenantId()),UUID.class);var a=b.auth.actor(s);p.feature(a,"workspace");attachment(a,true);var row=b.one("SELECT * FROM crm_workspace_attachment WHERE tenant_id=:tenant AND id=:id AND status='READY'",map("tenant",a.tenant().id(),"id",id));writable(a,(String)row.get("entityType"),(UUID)row.get("recordId"));b.version(row,expected);b.db.update("UPDATE crm_workspace_attachment SET status='DELETED',version=version+1 WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id));b.db.update("INSERT INTO sys_object_cleanup(id,tenant_id,object_key) VALUES(:id,:tenant,:key) ON CONFLICT DO NOTHING",map("id",UUID.randomUUID(),"tenant",a.tenant().id(),"key",row.get("objectKey")));b.audit(a,"WORKSPACE_ATTACHMENT_DELETED",(String)row.get("entityType"),(UUID)row.get("recordId"),expected+1,trace);return map("removed",true);});}
}
